PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO schema_migrations(version) VALUES(1);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,totp_secret TEXT,totp_enabled INTEGER NOT NULL DEFAULT 0,enabled INTEGER NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(id INTEGER PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,user_id INTEGER NOT NULL,expires_at DATETIME NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,last_seen_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,ip_address TEXT,user_agent TEXT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_sessions_expiry ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS wireguard_configs(id INTEGER PRIMARY KEY,interface_name TEXT NOT NULL,config_text TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS wireguard_status(id INTEGER PRIMARY KEY,interface_name TEXT NOT NULL,state TEXT NOT NULL,endpoint TEXT,latest_handshake DATETIME,rx_bytes INTEGER DEFAULT 0,tx_bytes INTEGER DEFAULT 0,last_error TEXT,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_wg_status_created ON wireguard_status(created_at DESC);
CREATE TABLE IF NOT EXISTS dns_servers(id INTEGER PRIMARY KEY,name TEXT NOT NULL,address TEXT NOT NULL,via_tunnel INTEGER NOT NULL DEFAULT 0,enabled INTEGER NOT NULL DEFAULT 1,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS dns_rules(id INTEGER PRIMARY KEY,domain TEXT NOT NULL UNIQUE,action TEXT NOT NULL,static_ip TEXT,enabled INTEGER NOT NULL DEFAULT 1,applied INTEGER NOT NULL DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_dns_rules_action ON dns_rules(action,enabled);
CREATE TABLE IF NOT EXISTS socks_users(id INTEGER PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS socks_settings(id INTEGER PRIMARY KEY CHECK(id=1),enabled INTEGER NOT NULL DEFAULT 0,listen_addr TEXT NOT NULL DEFAULT '127.0.0.1',port INTEGER NOT NULL DEFAULT 1080,route_via_wireguard INTEGER NOT NULL DEFAULT 1,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO socks_settings(id) VALUES(1);
CREATE TABLE IF NOT EXISTS geosite_files(id INTEGER PRIMARY KEY,path TEXT NOT NULL,url TEXT NOT NULL,sha256 TEXT,version TEXT,status TEXT,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS geosite_categories(id INTEGER PRIMARY KEY,tag TEXT NOT NULL UNIQUE,action TEXT NOT NULL DEFAULT 'direct',selected INTEGER NOT NULL DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_geosite_selected ON geosite_categories(selected,action);
CREATE TABLE IF NOT EXISTS acl_rules(id INTEGER PRIMARY KEY,scope TEXT NOT NULL,cidr TEXT NOT NULL,ip_version INTEGER NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,applied INTEGER NOT NULL DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE(scope,cidr));
CREATE INDEX IF NOT EXISTS idx_acl_scope ON acl_rules(scope,enabled);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY,user_id INTEGER,action TEXT NOT NULL,details TEXT,ip_address TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at DESC);
